from pydantic import BaseModel, ValidationError

class Line(BaseModel):
    sku: str
    qty: int

class Cart(BaseModel):
    user_id: int
    items: list[Line]

try:
    Cart.model_validate({"user_id": "x", "items": [{"sku": "a", "qty": 1}, {"sku": "b"}]})
except ValidationError as exc:
    print(exc.error_count())                 # 2
    for e in exc.errors():
        print(e["loc"], e["type"])
    # ('user_id',) int_parsing
    # ('items', 1, 'qty') missing

from datetime import date
from pydantic import BaseModel, ValidationError, field_validator, model_validator

class Booking(BaseModel):
    tags: list[str] = []
    start: date
    end: date

    @field_validator("tags", mode="before")
    @classmethod
    def split_csv(cls, v):
        return v.split(",") if isinstance(v, str) else v

    @model_validator(mode="after")
    def check_dates(self):
        if self.end < self.start:
            raise ValueError("end must not be before start")
        return self

b = Booking(tags="vip,late", start="2025-01-01", end="2025-01-03")
print(b.tags)                              # ['vip', 'late']
try:
    Booking(start="2025-01-05", end="2025-01-01")
except ValidationError as e:
    print(e.errors()[0]["msg"])            # Value error, end must not be before start

from pydantic import BaseModel, ConfigDict, ValidationError

class Point(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid")
    x: int
    y: int

p = Point(x=1, y="2")
print({p: "origin-ish"}[Point(x=1, y=2)])    # origin-ish  (frozen -> hashable)
for bad in ({"x": 1, "y": 2, "z": 3}, {"x": "1", "y": 2}):
    try:
        Point.model_validate(bad, strict=True)
    except ValidationError as e:
        print(e.errors()[0]["type"])        # extra_forbidden, then int_type

class Account(BaseModel):
    model_config = ConfigDict(validate_assignment=True)
    balance: int

a = Account(balance=10)
try:
    a.balance = "lots"
except ValidationError:
    print("assignment rejected")             # assignment rejected

from decimal import Decimal
from pydantic import BaseModel, ConfigDict, computed_field, field_serializer
from pydantic.alias_generators import to_camel

class Invoice(BaseModel):
    model_config = ConfigDict(alias_generator=to_camel, populate_by_name=True)
    invoice_id: int
    unit_price: Decimal
    quantity: int

    @computed_field
    @property
    def total_price(self) -> Decimal:
        return self.unit_price * self.quantity

    @field_serializer("unit_price", "total_price", when_used="json")
    def money(self, v: Decimal) -> str:
        return f"{v:.2f}"

inv = Invoice.model_validate({"invoiceId": 9, "unitPrice": "2.5", "quantity": 3})
print(inv.invoice_id, inv.total_price)          # 9 7.5
print(inv.model_dump_json(by_alias=True))
# {"invoiceId":9,"unitPrice":"2.50","quantity":3,"totalPrice":"7.50"}
print(Invoice(invoice_id=1, unit_price=1, quantity=1).invoice_id)   # 1 (by name)

from pydantic import BaseModel
from pydantic_core import core_schema

class Color:
    def __init__(self, hex_: str):
        self.hex = hex_.lower()

    @classmethod
    def __get_pydantic_core_schema__(cls, source, handler):
        from_str = core_schema.no_info_after_validator_function(
            cls, core_schema.str_schema(pattern=r"^#[0-9a-fA-F]{6}$"))
        return core_schema.json_or_python_schema(
            json_schema=from_str,
            python_schema=core_schema.union_schema([core_schema.is_instance_schema(cls), from_str]),
            serialization=core_schema.plain_serializer_function_ser_schema(lambda c: c.hex),
        )

class Theme(BaseModel):
    primary: Color

t = Theme.model_validate_json('{"primary": "#FF8800"}')
print(t.primary.hex, t.model_dump_json())      # #ff8800 {"primary":"#ff8800"}
print(Theme(primary=Color("#000000")).primary.hex)   # #000000
print(Theme.__pydantic_core_schema__["type"])  # model
